import React, { useState, useEffect } from "react";
import Modal from "react-modal";
import "./Library.css";

function Library() {
  const [videos, setVideos] = useState([]);
  const [selectedFeedback, setSelectedFeedback] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    const fetchVideos = async () => {
      const userId = localStorage.getItem("user_id");
      if (!userId) return;

      try {
        const response = await fetch(`http://34.55.142.231:5000/videos/${userId}`);
        const data = await response.json();
        setVideos(data);
      } catch (error) {
        console.error("Error fetching videos:", error);
      }
    };

    fetchVideos();
  }, []);

  const openModal = (feedback) => {
    setSelectedFeedback(feedback);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedFeedback("");
  };

  return (
    <div className="resource-section">
      <h1>Library</h1>
      <div className="resource-content">
        {videos.length === 0 ? (
          <p>No videos uploaded yet.</p>
        ) : (
          <div className="video-container">
            {videos.map((video) => (
              <div key={video.video_id} className="video-card">
                <div className="video-card-content">
                  <video width="250" controls>
                    <source src={`http://34.55.142.231:5000/uploads/${video.video_filename}`} type="video/mp4" />
                    Your browser does not support the video tag.
                  </video>
                  <h3>{video.video_filename}</h3>
                  <p>Click Read More to view AI Feedback</p>
                  <button className="read-more-btn" onClick={() => openModal(video.feedback)}>Read More</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Feedback Modal */}
      <Modal
        isOpen={isModalOpen}
        onRequestClose={closeModal}
        contentLabel="Feedback Modal"
        style={{
          content: { top: "50%", left: "50%", transform: "translate(-50%, -50%)", width: "500px", padding: "20px" },
        }}
      >
        <h2>AI Feedback</h2>
        <div style={{ whiteSpace: "pre-line" }}>{selectedFeedback}</div>
        <button className="read-more-btn" onClick={closeModal} style={{ marginTop: "20px" }}>Close</button>
      </Modal>
    </div>
  );
}

export default Library;
